diff --git a/reproduce.js b/reproduce.js
new file mode 100644
index 0000000..f2d4130
--- /dev/null
+++ b/reproduce.js
@@ -0,0 +1,36 @@
+
+const fastify = require('fastify')()
+const replyFrom = require('.')
+
+fastify.register(replyFrom, {
+  base: 'http://localhost:3000/pub/'
+})
+
+fastify.get('/priv', (request, reply) => {
+  reply.send({ hello: 'world' })
+})
+
+fastify.get('/pub/*', (request, reply) => {
+  console.log(request.raw.url)
+  reply.from(request.raw.url)
+})
+
+fastify.listen({ port: 3000 }, (err, address) => {
+  if (err) throw err
+  console.log(`server listening on ${address}`)
+
+  const http = require('http')
+  http.get('http://localhost:3000/pub/../priv', (res) => {
+    let data = ''
+    res.on('data', (chunk) => {
+      data += chunk
+    })
+    res.on('end', () => {
+      console.log(data)
+      fastify.close()
+    })
+  }).on('error', (err) => {
+    console.log('Error: ' + err.message)
+    fastify.close()
+  })
+})

