@@ -0,0 +1,23 @@
+package cors
+
+import (
+"net/http"
+"net/http/httptest"
+"testing"
+)
+
+func TestReproduceVulnerability(t *testing.T) {
+handler := Middleware(nil, "example.com")
+
+req := httptest.NewRequest("GET", "http://anyurl.com", nil)
+req.Header.Set("Origin", "http://evil-example.com")
+w := httptest.NewRecorder()
+handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+// Do nothing
+})).ServeHTTP(w, req)
+
+allowedOrigin := w.Header().Get("Access-Control-Allow-Origin")
+if allowedOrigin != "http://evil-example.com" {
+t.Errorf("Vulnerable code should allow evil-example.com, but it did not. Got: %s", allowedOrigin)
+}
+}

