+
+func TestPathTraversal(t *testing.T) {
+// Create a temporary directory for the test
+tmpDir, err := ioutil.TempDir("", "helm-test")
+if err != nil {
+t.Fatalf("Failed to create temporary directory: %v", err)
+}
+defer os.RemoveAll(tmpDir)
+
+// Create a malicious tarball with a path traversal
+var buf bytes.Buffer
+gw := gzip.NewWriter(&buf)
+tw := tar.NewWriter(gw)
+
+// Add a file with a path traversal
+hdr := &tar.Header{
+Name: "../../../../../../../tmp/pwned",
+Mode: 0600,
+Size: int64(len("pwned")),
+}
+if err := tw.WriteHeader(hdr); err != nil {
+t.Fatalf("Failed to write tar header: %v", err)
+}
+if _, err := tw.Write([]byte("pwned")); err != nil {
+t.Fatalf("Failed to write tar content: %v", err)
+}
+
+tw.Close()
+gw.Close()
+
+// Extract the tarball
+extractor := &installer.TarGzExtractor{}
+err = extractor.Extract(&buf, tmpDir)
+if err == nil {
+t.Logf("Extraction did not return an error")
+}
+
+// Check if the file was created outside the target directory
+if _, err := os.Stat("/tmp/pwned"); err == nil {
+t.Errorf("Path traversal successful, file created at /tmp/pwned")
+os.Remove("/tmp/pwned")
+} else if !os.IsNotExist(err) {
+t.Errorf("Unexpected error checking for file: %v", err)
+}
+
+}

