+package main
+
+import (
+"fmt"
+"strings"
+)
+
+// This is the vulnerable function copied from the source
+func hostMatchesGlob_vulnerable(host string, domainGlob string) bool {
+if domainGlob != "" && domainGlob[0] == '*' {
+suffix := domainGlob[1:]
+if strings.HasSuffix(host, suffix) {
+return true
+}
+} else if domainGlob == host {
+return true
+}
+return false
+}
+
+// This is the fixed function
+func hostMatchesGlob_fixed(host string, domainGlob string) bool {
+host = strings.ToLower(strings.TrimSuffix(host, "."))
+domainGlob = strings.ToLower(domainGlob)
+
+if domainGlob != "" && domainGlob[0] == '*' {
+suffix := domainGlob[1:]
+if strings.HasSuffix(host, suffix) {
+return true
+}
+} else if domainGlob == host {
+return true
+}
+return false
+}
+
+func main() {
+fmt.Println("--- Vulnerable function ---")
+// Should be true, but is false
+fmt.Printf("Mismatch with different case: %v\n", hostMatchesGlob_vulnerable("Example.com", "example.com"))
+// Should be true, but is false
+fmt.Printf("Mismatch with trailing dot: %v\n", hostMatchesGlob_vulnerable("example.com.", "example.com"))
+
+fmt.Println("\n--- Fixed function ---")
+fmt.Printf("Match with different case: %v\n", hostMatchesGlob_fixed("Example.com", "example.com"))
+fmt.Printf("Match with trailing dot: %v\n", hostMatchesGlob_fixed("example.com.", "example.com"))
+}

