+                        case "email":
+                                r.summary.Config.User.Email = val
+                        }
+                case "github":
+                        switch key {
+                        case "user":
+                                r.summary.Config.GithubToken.Username = val
+                        case "token":
+                                r.summary.Config.GithubToken.Token = val
+                        }
+                }
+
+        }
+        return nil
 }

