+
+async function start() {
+
+    try {
+        await server.register([require('./lib'), require('hapi-auth-cookie')]);
+
+        server.auth.strategy('session', 'cookie', {
+            password: 'password-should-be-32-characters',
+            isSecure: false
+        });
+
+        server.route({
+            method: 'GET',
+            path: '/h',
+            config: {
+                auth: 'session',
+                handler: (request, reply) => {
+                    reply('hapi');
+                }
+            }
+        });
+
+        server.subscription('/h', { auth: { mode: 'required' } });
+
+        await server.start();
