+
+        ws.on('message', (data) => {
+            console.log(data);
+        });
+
+        ws.on('close', () => {
+            console.log('Disconnected');
+        });
+
+        ws.on('error', (error) => {
+            console.log('Error:', error.message);
+        });
+    } catch (err) {
