+++ b/test/reproduce.js
@@ -0,0 +1,74 @@
+
+const { auth } = require('../');
+const { MemoryStore } = require('express-session');
+const request = require('supertest');
+const { oidc: { code, id_token, max_age } } = require('./fixture/good_auth');
+const { regular_user: { password, username } } = require('./fixture/users.json');
+
+const port = 3000;
+const default_config = {
+  secret: 'a secret',
+  auth0Logout: false,
+  baseURL: `http://localhost:${port}`,
+  clientID: 'test-client-id',
+  issuerBaseURL: 'https://op.example.com',
+  routes: {
+    login: false,
+    postLogoutRedirect: '/custom-logout'
+  }
+};
+
+const get_app = (config) => {
+  const express = require('express');
+  const app = express();
+
+  app.use(auth({
+    ...default_config,
+    ...config,
+  }));
+
+  app.get('/', (req, res) => {
+    res.json({
+      'session_id': req.sessionID
+    });
+  });
+
+  return app;
+}
+
+describe('Session Fixation', function() {
+  it('should regenerate session on login', function(done) {
+    const app = get_app();
+    const agent = request.agent(app);
+
+    agent
+      .get('/')
+      .expect(200)
+      .catch(done)
+      .then(res => {
+        console.log(res.headers);
+        const cookies_before_login = res.headers['set-cookie'];
+
+        agent
+          .post('/callback')
+          .type('form')
+          .send({ code, id_token, max_age, username, password })
+          .expect(302)
+          .catch(done)
+          .then(res => {
+            agent
+              .get('/')
+              .expect(200)
+              .catch(done)
+              .then(res => {
+                const cookies_after_login = res.headers['set-cookie'];
+                if (cookies_before_login[0].split(';')[0] === cookies_after_login[0].split(';')[0]) {
+                  done('Session ID was not regenerated');
+                } else {
+                  done();
+                }
+              });
+          });
+  });
+});
+});

